const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const categories=['All','Repair','Refine','Reset','Activate','Restructure','Optimize','Amplify','Protect','Renew','Calm','Base'];
let products=[];
const dialog=$('#product-dialog'), searchDialog=$('#search-dialog');
function openDialog(d){d.showModal();document.body.classList.add('locked')}
$$('dialog').forEach(d=>{d.addEventListener('close',()=>document.body.classList.remove('locked'));d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
$('#menu-toggle')?.addEventListener('click',()=>{const b=$('#menu-toggle'),m=$('#mobile-menu'),on=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(on));b.setAttribute('aria-label',on?'Close navigation':'Open navigation');m.style.top=$('.site-header').getBoundingClientRect().bottom+'px';m.classList.toggle('open',on)});
addEventListener('scroll',()=>{const m=$('#mobile-menu');if(m?.classList.contains('open'))m.style.top=$('.site-header').getBoundingClientRect().bottom+'px'},{passive:true});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#mobile-menu')?.classList.remove('open');$('#menu-toggle')?.setAttribute('aria-expanded','false')}});
$$('[data-search]').forEach(b=>b.addEventListener('click',()=>{openDialog(searchDialog);$('#global-search').focus()}));
function productType(p){return /capsule/i.test(p.name)?'Capsules':/water/i.test(p.name)?'Research water':/kit/i.test(p.name)?'Research accessory':/blend|\//i.test(p.name)?'Research blend':'Research material'}
function card(p){return `<article class="product-card"><a class="product-art" href="product.html?item=${encodeURIComponent(p.slug)}" aria-label="View ${safe(p.name)}"><span class="product-label">${safe(p.categories[0]||'The collection')}</span><img src="${p.image}" width="900" height="900" loading="lazy" alt="BKG ${safe(p.name)} bottle"></a><button class="quick-view" data-product="${safe(p.slug)}" aria-label="Quick view ${safe(p.name)}">+</button><div class="product-meta"><div><h3><a href="product.html?item=${encodeURIComponent(p.slug)}">${safe(p.name)}</a></h3><div class="product-type">${productType(p)}</div></div><span class="price">${money(p.price)}</span></div></article>`}
function bindQuick(){ $$('[data-product]').forEach(b=>{b.onclick=()=>showProduct(products.find(p=>p.slug===b.dataset.product))})}
function productDetail(p){return `<div class="quick-layout"><div class="quick-image"><img src="${p.image}" alt="${safe(p.name)} — original BKG packaging"></div><div class="quick-content"><span class="eyebrow">BKG PERFORMANCE LAB / ${safe(p.categories[0]||'COLLECTION')}</span><${$('#product-page')?'h1':'h2'}>${safe(p.name)}</${$('#product-page')?'h1':'h2'}><p class="quick-price">${money(p.price)} <small style="font-size:10px">USD</small></p><p>${productType(p)} from the BKG collection. Explore the current product listing for complete product information, availability, and ordering.</p>${p.details?.length?`<dl class="product-specs">${p.details.map(d=>{const [k,...v]=d.split(':');return `<div><dt>${safe(k)}</dt><dd>${safe(v.join(':').trim())}</dd></div>`}).join('')}</dl>`:''}<p style="margin-top:18px">For laboratory research use only. Not for human or animal use.</p><a class="btn" href="${p.url}" target="_blank" rel="noopener">View product at BKG <span class="arrow">↗</span></a><p class="fine">Opens BKG’s existing store. Current price and availability are confirmed there.</p></div></div>`}
function showProduct(p){if(!p)return;$('#product-dialog-content').innerHTML=productDetail(p);openDialog(dialog)}
function searchResults(){const q=$('#global-search').value.toLowerCase().trim();const matches=products.filter(p=>p.name.toLowerCase().includes(q)).slice(0,7);$('#search-results').innerHTML=matches.length?matches.map(p=>`<a class="search-result" href="product.html?item=${p.slug}"><img src="${p.image}" alt=""><div>${safe(p.name)}</div><span>${money(p.price)} ↗</span></a>`).join(''):'<p>No matching materials. Try a different product name.</p>'}
$('#global-search')?.addEventListener('input',searchResults);
function renderCatalog(){const grid=$('#catalog-grid');if(!grid)return;const q=$('#catalog-search').value.trim().toLowerCase(),cat=$('#categories .active')?.dataset.category||'All',sort=$('#sort').value;let list=products.filter(p=>(cat==='All'||p.categories.includes(cat))&&p.name.toLowerCase().includes(q));if(sort==='price-low')list.sort((a,b)=>a.price-b.price);if(sort==='price-high')list.sort((a,b)=>b.price-a.price);if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));grid.innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h3>No materials found.</h3><p>Try a different name or explore another category.</p><button class="btn outline" id="reset-filters">Clear filters <span>↗</span></button></div>';$('#result-count').textContent=`${list.length} ${list.length===1?'material':'materials'}${cat!=='All'?' · '+cat:''}`;$('#reset-filters')?.addEventListener('click',()=>{$('#catalog-search').value='';$$('#categories button').forEach(b=>{b.classList.toggle('active',b.dataset.category==='All');b.setAttribute('aria-pressed',String(b.dataset.category==='All'))});renderCatalog()});bindQuick()}
async function initProducts(){try{const res=await fetch('products.json');if(!res.ok)throw Error('Catalog unavailable');products=await res.json();if($('#featured-grid')){const slugs=['bpc-157-10mg','ghk-cu-50mg','mots-c-10mg','nad-500mg'];let picks=slugs.map(s=>products.find(p=>p.slug===s)).filter(Boolean);if(picks.length<4)picks=[products.find(p=>p.name==='BPC-157 10mg'),products.find(p=>p.name==='GHK-Cu 100mg'),products.find(p=>p.name==='MOTS-C 10mg'),products.find(p=>p.name==='NAD+ 500mg')].filter(Boolean);$('#featured-grid').innerHTML=picks.map(card).join('');bindQuick()}if($('#categories')){const initial=new URLSearchParams(location.search).get('category')||'All';$('#categories').innerHTML='<span class="eyebrow">Shop by category</span>'+categories.map(c=>`<button data-category="${c}" class="${c===initial?'active':''}" aria-pressed="${c===initial}">${c}<span>${c==='All'?products.length:products.filter(p=>p.categories.includes(c)).length}</span></button>`).join('');if(!$('#categories .active'))$('#categories button').classList.add('active');$$('#categories button').forEach(b=>b.addEventListener('click',()=>{$$('#categories button').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});const u=new URL(location);if(b.dataset.category==='All')u.searchParams.delete('category');else u.searchParams.set('category',b.dataset.category);history.replaceState(null,'',u);renderCatalog()}));$('#catalog-search').addEventListener('input',renderCatalog);$('#sort').addEventListener('change',renderCatalog);renderCatalog()}if($('#product-page')){const slug=new URLSearchParams(location.search).get('item');const p=products.find(p=>p.slug===slug);$('#product-page').innerHTML=p?productDetail(p):'<div class="empty"><h1 style="font-size:50px">Material not found.</h1><a class="btn" href="shop.html">Explore the collection ↗</a></div>';if(p){document.title=`${p.name} | BKG Performance Lab`;$('#product-breadcrumb').textContent=p.name}}searchResults()}catch(e){$$('#catalog-grid,#featured-grid,#product-page').forEach(el=>el.innerHTML='<p>The collection could not load. <a href="https://www.bkgperformancepartners.com">Visit the BKG store ↗</a></p>')}}
initProducts();
function prepareEmail(form,type){form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const d=new FormData(form),lines=[];for(const [key,val] of d.entries())lines.push(`${key}: ${val}`);const subject=type==='affiliate'?'BKG Affiliate Application':`BKG Inquiry — ${d.get('Subject')||'The Lab'}`;const body=lines.join('\r\n\r\n');const url=`mailto:Sales@BKGPerformance.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;const status=$('.application-status',form);status.innerHTML=`<strong>Your ${type==='affiliate'?'application':'message'} is ready to review.</strong><p style="margin:8px 0">Nothing has been sent. Open the draft in your email app, or download it and email it to Sales@BKGPerformance.com.</p><div class="actions"><a class="btn" href="${safe(url)}">Open email draft <span>↗</span></a><button type="button" class="text-link" data-download-draft>Download text <span>↓</span></button></div>`;$('[data-download-draft]',status).onclick=()=>{const blob=new Blob([`To: Sales@BKGPerformance.com\r\nSubject: ${subject}\r\n\r\n${body}`],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=type==='affiliate'?'BKG-Affiliate-Application.txt':'BKG-Inquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};status.scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'nearest'})})}
if($('#affiliate-form'))prepareEmail($('#affiliate-form'),'affiliate');if($('#contact-form'))prepareEmail($('#contact-form'),'contact');
const videoObservers=new IntersectionObserver(entries=>entries.forEach(({target:v,isIntersecting})=>{if(isIntersecting&&!reduced.matches&&!v.dataset.paused)v.play().catch(()=>{});else v.pause()}),{threshold:.1});
$$('video').forEach(v=>{if(reduced.matches){v.pause();v.removeAttribute('autoplay')}else{if(v.dataset.src){v.src=v.dataset.src;v.load()}videoObservers.observe(v)}});
$$('[data-pause-video]').forEach(b=>b.addEventListener('click',()=>{const v=$(b.dataset.pauseVideo);if(v.paused){v.dataset.paused='';v.play().catch(()=>{});b.textContent='Pause film';b.setAttribute('aria-pressed','false')}else{v.dataset.paused='true';v.pause();b.textContent='Play film';b.setAttribute('aria-pressed','true')}}));
const story=$('#vial-story');let storyTrigger;
function storyStep(i){$$('.story-step').forEach((s,j)=>{s.classList.toggle('active',i===j);$('button',s).setAttribute('aria-current',String(i===j))});$('#story-counter')&&($('#story-counter').textContent=`0${i+1} / 03`)}
$$('[data-story-step]').forEach(b=>b.addEventListener('click',()=>{const n=Number(b.dataset.storyStep);storyStep(n);if(storyTrigger&&!reduced.matches)window.scrollTo({top:storyTrigger.start+(storyTrigger.end-storyTrigger.start)*(n/3+.12),behavior:'smooth'})}));
const labChapters=[{eyebrow:'01 / CURATED SELECTION',title:'A considered<br><em>collection.</em>',text:'Research begins with the materials you choose. The Lab brings BKG’s carefully selected research products together in one organized collection.'},{eyebrow:'02 / EDUCATION FIRST',title:'Room for<br><em>discovery.</em>',text:'Explore product information, understand the research-only framework, and ask questions. Education is central to the BKG community.'},{eyebrow:'03 / TRUSTED RELATIONSHIPS',title:'Built on<br><em>connection.</em>',text:'BKG works with manufacturers who share its commitment to quality and integrity. Reach out to the team for product information and supporting documentation.'}];
let labTrigger,labIndex=-1;
function setLab(i){if(i===labIndex)return;labIndex=i;const c=labChapters[i];$('#lab-chapter-eyebrow').textContent=c.eyebrow;$('#lab-chapter-title').innerHTML=c.title;$('#lab-chapter-text').textContent=c.text;$$('[data-lab-step]').forEach((b,j)=>{b.classList.toggle('active',j===i);b.setAttribute('aria-current',String(j===i))})}
$$('[data-lab-step]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.labStep);setLab(i);if(labTrigger&&!reduced.matches)scrollTo({top:labTrigger.start+(labTrigger.end-labTrigger.start)*(i/3+.12),behavior:'smooth'})}));
if($('#lab-scroll'))setLab(0);
if(window.gsap&&window.ScrollTrigger){gsap.registerPlugin(ScrollTrigger);const mm=gsap.matchMedia();mm.add('(prefers-reduced-motion: no-preference)',()=>{document.body.classList.add('js-motion');$$('.reveal').forEach(el=>gsap.to(el,{opacity:1,y:0,duration:.8,ease:'power2.out',scrollTrigger:{trigger:el,start:'top 91%',once:true}}));if($('.hero')){gsap.to('.bottle-main',{y:45,rotation:-2,ease:'none',scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:1}});gsap.to('.bottle-left',{y:-30,rotation:-33,ease:'none',scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:1}});gsap.to('.bottle-right',{y:70,rotation:28,ease:'none',scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:1}})}if(story){const tl=gsap.timeline({scrollTrigger:{trigger:story,start:'top 87px',end:'bottom bottom',scrub:.65,onUpdate:s=>{storyStep(Math.min(2,Math.floor(s.progress*3)));$('.progress-fill',story).style.width=(s.progress*100)+'%'}}});storyTrigger=tl.scrollTrigger;tl.to('.vial-assembly',{rotation:-7,duration:1,ease:'none'},0).to('.vial-cap',{y:-105,duration:.4,ease:'power1.inOut'},0).to('.vial-body',{y:25,duration:.4},0).to('.vial-cap',{y:0,duration:.35,ease:'power1.inOut'},.65).to('.vial-body',{y:0,duration:.35},.65)}if($('#lab-scroll')){labTrigger=ScrollTrigger.create({trigger:'#lab-scroll',start:'top 87px',end:'bottom bottom',onUpdate:s=>{setLab(Math.min(2,Math.floor(s.progress*3)));$('#lab-progress').style.width=s.progress*100+'%'}});gsap.to('#lab-video',{scale:1.24,xPercent:-4,ease:'none',scrollTrigger:{trigger:'#lab-scroll',start:'top top',end:'bottom bottom',scrub:1}})}return()=>{document.body.classList.remove('js-motion');storyTrigger=null;labTrigger=null}})}
reduced.addEventListener('change',()=>{$$('video').forEach(v=>{if(reduced.matches)v.pause();else if(!v.dataset.paused){if(!v.src&&v.dataset.src)v.src=v.dataset.src;v.play().catch(()=>{})}})});
